officedepot.com.apply:
const input = document.querySelector('#OdCart input#coupon-code-od-coupon-input'); 
const button = document.querySelector('.od-coupon-list-action-apply'); 
input.dispatchEvent(new Event('input', { bubbles: true })); 
input.dispatchEvent(new Event('blur')); 
input.dispatchEvent(new Event('focus')); 
input.dispatchEvent(new Event('change', { bubbles: true })); 
setTimeout(function() {
  document.querySelector('.od-coupon-list-action-apply').removeAttribute('disabled'); 
  button.click();
}, 1000);

