abbonamenti.it.apply:
try {
  const DELAY = 300;
  const SUBMIT = `button#button-promo`;
  const COUPON = `input#promo-field`;

  const EVENTS = 
  [new Event('input', { bubbles: true }), 
  new Event('change'), 
  new Event('blur'), 
  new Event('focus')];
  
  EVENTS.forEach(EVENT => { 
    document.querySelector(COUPON).dispatchEvent(EVENT); 
  });
  
  setTimeout(() => {
    document.querySelector(SUBMIT).click();
  },DELAY)
}catch(e){}

